PRAGMA foreign_keys=ON;
CREATE TABLE dim_patient(patient_id INTEGER PRIMARY KEY, sex TEXT NOT NULL, age REAL, age_band TEXT NOT NULL);
CREATE TABLE fact_admission(admission_id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES dim_patient, admission_type TEXT NOT NULL);
CREATE TABLE fact_icu_stay(stay_id INTEGER PRIMARY KEY, admission_id INTEGER NOT NULL REFERENCES fact_admission, patient_id INTEGER NOT NULL REFERENCES dim_patient, unit TEXT NOT NULL, los_days REAL NOT NULL CHECK(los_days>=0), outcome INTEGER NOT NULL CHECK(outcome IN(0,1)), fold INTEGER NOT NULL);
CREATE INDEX stay_patient ON fact_icu_stay(patient_id);
CREATE INDEX stay_admission ON fact_icu_stay(admission_id);
CREATE INDEX stay_unit ON fact_icu_stay(unit);
CREATE TABLE fact_diagnosis(admission_id INTEGER NOT NULL REFERENCES fact_admission, code TEXT NOT NULL, version INTEGER NOT NULL, diagnosis TEXT NOT NULL, PRIMARY KEY(admission_id,code,version));
CREATE INDEX diagnosis_label ON fact_diagnosis(diagnosis);
CREATE TABLE fact_prescription(admission_id INTEGER NOT NULL REFERENCES fact_admission, drug TEXT NOT NULL, orders INTEGER NOT NULL CHECK(orders>0), PRIMARY KEY(admission_id,drug));
CREATE TABLE fact_prediction(stay_id INTEGER NOT NULL REFERENCES fact_icu_stay, hour INTEGER NOT NULL CHECK(hour IN(1,24,48,72)), probability_raw REAL NOT NULL CHECK(probability_raw BETWEEN 0 AND 1), probability_cal REAL NOT NULL CHECK(probability_cal BETWEEN 0 AND 1), PRIMARY KEY(stay_id,hour));
CREATE INDEX prediction_hour ON fact_prediction(hour);
CREATE TABLE model_metric(experiment TEXT NOT NULL, hour INTEGER NOT NULL, model TEXT NOT NULL, stays INTEGER, patients INTEGER, prevalence REAL, mean_probability REAL, auroc REAL, ap REAL, brier REAL, PRIMARY KEY(experiment,hour,model));
CREATE TABLE calibration_bin(hour INTEGER, model TEXT, bin INTEGER, n INTEGER, mean_probability REAL, observed_fraction REAL);
CREATE TABLE feature_quality(feature TEXT, hour INTEGER, risk_stays INTEGER, known INTEGER, missing_fraction REAL, median REAL, q25 REAL, q75 REAL);
CREATE TABLE feature_importance(hour INTEGER, output TEXT, group_name TEXT, group_label TEXT, importance_pp REAL, rank INTEGER, sample_patients INTEGER);
CREATE TABLE pipeline_check(rule TEXT PRIMARY KEY, passed INTEGER NOT NULL, checked INTEGER NOT NULL, failures INTEGER NOT NULL, detail TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE VIEW bi_cohort AS SELECT p.sex,p.age_band,s.unit,COUNT(*) AS icu_stays,COUNT(DISTINCT s.patient_id) AS patients,COUNT(DISTINCT s.admission_id) AS admissions,AVG(s.los_days) AS mean_los_days,AVG(s.outcome*1.0) AS mortality_90d FROM fact_icu_stay s JOIN dim_patient p USING(patient_id) GROUP BY p.sex,p.age_band,s.unit;
